def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]
    count = 2
    value = (v1 + v2) / count

    return {
        "value": value,
        "trace": {
            "v1": v1,
            "v2": v2,
            "count": count,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }
